fn numpy_insert<T>(mut arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    // Precondition: idx must be in 0..=arr.len()
    assert!(idx <= arr.len(), "Insertion index out of bounds");

    // Vec::insert shifts all elements at positions >= idx to the right
    arr.insert(idx, value);
    arr
}

